add_action( 'init', 'perfectpixel_storefront_homepage_sections', 20 );

function perfectpixel_storefront_homepage_sections() {
	$map = array(
		'content'      => array( 'storefront_homepage_content', 10 ),
		'categories'   => array( 'storefront_product_categories', 20 ),
		'recent'       => array( 'storefront_recent_products', 30 ),
		'featured'     => array( 'storefront_featured_products', 40 ),
		'popular'      => array( 'storefront_popular_products', 50 ),
		'on_sale'      => array( 'storefront_on_sale_products', 60 ),
		'best_selling' => array( 'storefront_best_selling_products', 70 ),
	);
	foreach ( array_filter( array_map( 'trim', explode( ',', '{{storefront_removed_sections}}' ) ) ) as $key ) {
		if ( isset( $map[ $key ] ) ) {
			remove_action( 'homepage', $map[ $key ][0], $map[ $key ][1] );
		}
	}
}
